-- create-table /TROTTO/OTTO_SHOPS
CREATE TABLE "/TROTTO/OTTO_SHOPS" (
  "/RT/TENANT" TEXT NOT NULL,
  "SHOP_ID" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  CONSTRAINT "/TROTTO/OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#FK#CONNECTION" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TROTTO/OTTO_CONNECTIONS" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#CK#SHOP_ID" CHECK ("SHOP_ID" IS NULL OR (length("SHOP_ID") <= 12)),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80))
) STRICT;

-- rebuild table /TRFIN/COMPANIES: alter-type /TRFIN/COMPANIES./TROTTO/OTTO_ID (CHAR(20) -> CHAR(32)); add-column /TRFIN/COMPANIES./TROTTO/ACTIVE (BOOL); add-column /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (CHAR(12)); add-foreign-key /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (references /TROTTO/OTTO_SHOPS)
CREATE TABLE "/TRFIN/COMPANIES#NEW" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  "/TROTTO/OTTO_ID" TEXT,
  "/TROTTO/ACTIVE" INTEGER NOT NULL DEFAULT 0,
  "/TROTTO/MAIN_SHOP" TEXT,
  CONSTRAINT "/TRFIN/COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "/TRFIN/COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#/TROTTO/MAIN_SHOP" FOREIGN KEY ("/RT/TENANT", "/TROTTO/MAIN_SHOP") REFERENCES "/TROTTO/OTTO_SHOPS" ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON"))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/TROTTO/OTTO_ID" CHECK ("/TROTTO/OTTO_ID" IS NULL OR (length("/TROTTO/OTTO_ID") <= 32)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/TROTTO/ACTIVE" CHECK ("/TROTTO/ACTIVE" IS NULL OR ("/TROTTO/ACTIVE" IN (0, 1))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/TROTTO/MAIN_SHOP" CHECK ("/TROTTO/MAIN_SHOP" IS NULL OR (length("/TROTTO/MAIN_SHOP") <= 12))
) STRICT;
INSERT INTO "/TRFIN/COMPANIES#NEW" ("/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON", "/TROTTO/OTTO_ID") SELECT "/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON", "/TROTTO/OTTO_ID" FROM "/TRFIN/COMPANIES";
DROP TABLE "/TRFIN/COMPANIES";
ALTER TABLE "/TRFIN/COMPANIES#NEW" RENAME TO "/TRFIN/COMPANIES";

